void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    vec3 col = texture(iChannel0, fragCoord/iResolution.xy).rgb;

    float depth = texelFetch(iChannel0, ivec2(fragCoord), 0).a;
    float rightDepth = texelFetch(iChannel0, ivec2(fragCoord) + ivec2(-1,0), 0).a - depth;
    float leftDepth = depth - texelFetch(iChannel0, ivec2(fragCoord) + ivec2(1,0), 0).a;
    float upDepth = texelFetch(iChannel0, ivec2(fragCoord) + ivec2(0,-1), 0).a - depth;
    float downDepth = depth - texelFetch(iChannel0, ivec2(fragCoord) + ivec2(0,1), 0).a;

    float xAngle = (rightDepth - leftDepth) * 50.0;
    float yAngle = (upDepth - downDepth) * 50.0;
    float edge = length(vec2(xAngle,yAngle));

    if(edge < 0.5){
        edge = 0.0;
    }

    // Output to screen
    fragColor = vec4(col - vec3(edge),1.0);
}

float sphereSDF(vec3 p, float r){
    return length(p) - r;
}
float cubeSDF(vec3 p, vec3 dim){
    vec3  p2 = vec3(clamp(p.x,-dim.x,dim.x),clamp(p.y,-dim.y,dim.y),clamp(p.z,-dim.z,dim.z));
    return length(p-p2);
}
float planeSDF(vec3 p){
    return p.y;
}
float heightSDF(vec3 p){
    return p.y - 10.0 * texture(iChannel2, p.xz * 0.01).r;
}

float worldSDF(vec3 p){
    return min(
        sphereSDF(p - vec3(0.,2.,0.), 1.0),
        min(
            sphereSDF(p - vec3(0.,-1.,1.), 1.0),
            min(
                heightSDF(p - vec3(0.,-10.,0.)), 
                min(
                    sphereSDF(p, 1.0),
                    cubeSDF(p - vec3(0.0,0.,0.), vec3(3.,.1,.1))
                    )
                )
            )
        );
}
vec3 worldCol(vec3 p){
    return 
    vec3(0.8,0.5,0.3) * length(mix(mix(mix(texture(iChannel0, p * 0.1).rgb,texture(iChannel0, p * 0.01).rgb,0.5),texture(iChannel0, p * 0.05).rgb,0.5),texture(iChannel0, p * 0.5).rgb,0.1));
}

//raycast function. iterates through world and returns the color at that position
vec4 raycast(vec3 pos, vec3 dir){
    pos += dir * minStep * hash33(uvec3(pos)).r;
    for(int i = 0; i < maxIters; i++){
        float d = worldSDF(pos);
        if(d < inflation){
            pos -= dir * inflation;
            break;
        }
        pos += dir * max(minStep,d);
        if(length(pos - camPos) > renderDist){
            return texture(iChannel1, pos);
        }
    }
    return vec4(worldCol(pos),1.0/(1.0+length(pos)));
}

//render
void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    camPos = vec3(-sin(iTime)*5.,0,-cos(iTime)*5.);
    camDir = rotY(camDir,-iTime);
    // Normalized pixel coordinates (from -0.5 to 0.5)
    vec2 uv = fragCoord/iResolution.xy - 0.5;
    //rescale such that everything is square (x values can be beyond -0.5 to 0.5)
    uv = uv * iResolution.xy / iResolution.xx;

    vec3 dir = dirFromScreen(uv, cos(fov/180.*3.1415));

    // Output to screen
    fragColor = raycast(camPos,dir);
}

//camera
float fov = 60.0;//field of view, in degrees.
vec3 camPos = vec3(3., 1.1, -3.);//position of camera
mat3 camDir = mat3(1,0,0,0,1,0,0,0,1);//matrix rotation of camera

//performance
float minStep = 0.01;//min step per ray
float inflation = 0.001;//distance from surface for a hit
float renderDist = 146.0;//max distance to send ray
int maxIters = 256;//max iters to send ray\

const uint k = 1103515245U;
vec3 hash33( uvec3 x )
{
    x = ((x>>8U)^x.yzx)*k;
    x = ((x>>8U)^x.yzx)*k;
    x = ((x>>8U)^x.yzx)*k;

    return vec3(x)*(1.0/float(0xffffffffU));
}

//rotate a matrix around x axis
mat3 rotX(mat3 p, float a){
    return p * mat3(
        1,  0,     0,
        0, cos(a),-sin(a),
        0, sin(a), cos(a));
}
//rotate a matrix around y axis
mat3 rotY(mat3 p, float a){
    return p * mat3(
        cos(a), 0, sin(a),
          0,    1,   0,
       -sin(a), 0, cos(a));
}
//rotate a matrix around z axis
mat3 rotZ(mat3 p, float a){
    return p * mat3(
        cos(a),-sin(a),0,
        sin(a), cos(a),0,
          0,     0,    1);
}

//get direction from screen position
vec3 dirFromScreen(vec2 uv, float d){
    vec3 rawDir = vec3(uv,d);
    return normalize(camDir[0] * rawDir.x + camDir[1] * rawDir.y + camDir[2] * rawDir.z);
}
